param([string]$HostName='localhost',[int]$Port=5432,[string]$Database='habitflow',[string]$Username='postgres')
$ErrorActionPreference='Stop'
if (-not $env:PGPASSWORD) { $secure=Read-Host 'Senha do PostgreSQL' -AsSecureString; $env:PGPASSWORD=[Runtime.InteropServices.Marshal]::PtrToStringAuto([Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)) }
try { $out=& psql -h $HostName -p $Port -U $Username -d $Database -v ON_ERROR_STOP=1 -tAc "select exists(select 1 from information_schema.schemata where schema_name='habitflow'), (select count(*) from information_schema.tables where table_schema='habitflow');" 2>&1; if($LASTEXITCODE -ne 0){throw "$out"}; if($out -notmatch 't') { Write-Error 'ERRO: schema habitflow ausente.'; exit 4 }; if($out -match '\|\s*0') { Write-Error 'ERRO: tabelas ausentes no schema habitflow.'; exit 5 }; Write-Host 'OK: Conexão com PostgreSQL validada.'; exit 0 } catch { $m="$_"; if($m -match '28P01'){Write-Error 'ERRO 28P01: A senha do PostgreSQL está incorreta para o usuário informado.'; exit 28}; if($m -match '3D000'){Write-Error 'ERRO 3D000: O banco informado não existe.'; exit 30}; Write-Error 'ERRO conexão: Não foi possível conectar ao PostgreSQL.'; exit 1 }
